package app.wattlo.phone

import android.app.Activity
import android.graphics.drawable.GradientDrawable
import android.os.Bundle
import android.util.TypedValue
import android.view.Gravity
import android.view.ViewGroup.LayoutParams.WRAP_CONTENT
import android.widget.FrameLayout
import android.widget.LinearLayout
import android.widget.ScrollView
import android.widget.TextView
import app.wattlo.Palette

/**
 * The open-source notices: Wattlo's own origin and the licences of the libraries, as one text that scrolls.
 * The text is assets/licenses.txt, generated by tools/update_licenses.py from the real dependencies.
 */
class LicensesActivity : Activity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val ui = Ui(this)
        val notices = runCatching { assets.open("licenses.txt").bufferedReader().use { it.readText() } }
            .getOrDefault("https://github.com/termit-uanic/wattlo")
        val pad = ui.dp(16f).toInt()
        val card = TextView(this).apply {
            text = notices
            setTextColor(Palette.GREY)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 12.5f)
            setLineSpacing(0f, 1.15f)
            setTextIsSelectable(true)
            setPadding(pad, pad, pad, pad)
            background = GradientDrawable().apply { cornerRadius = ui.dp(22f); setColor(Palette.CARD) }
        }
        val column = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(pad, pad, pad, pad * 2)
            addView(ui.label(26f, Palette.WHITE, bold = true).apply { text = getString(R.string.licenses_title) })
            addView(card, ui.lp(14f))
        }
        val width = minOf(resources.displayMetrics.widthPixels, ui.dp(560f).toInt())
        setContentView(ScrollView(this).apply {
            padForSystemBars()
            addView(column, FrameLayout.LayoutParams(width, WRAP_CONTENT, Gravity.CENTER_HORIZONTAL))
        })
    }
}
